def coefficients(rows):
    denominator = sum(F(x)*F(x) for row in rows for x in row)
    return [F(1)] + [
        2*sum(F(row[i])*F(row[i+k])
              for row in rows for i in range(47-k))/denominator
        for k in range(1,47)
    ]

